import {rstring,sameNumber} from './b35-model.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,index,pressed=false,extra='')=>`<button type="button" data-x="a35-${action}"${index===undefined?'':` data-index="${esc(index)}"`} aria-pressed="${!!pressed}" ${extra}>${esc(label)}</button>`;
const input=(key,label,value,placeholder='')=>`<label class="a35-field"><span>${esc(label)}</span><input data-xfield="${esc(key)}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off" maxlength="160"></label>`;
const select=(key,label,value,options)=>`<label class="a35-field"><span>${esc(label)}</span><select data-xfield="${esc(key)}"><option value="">选择</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const lin=([a,b])=>{let k=rstring(a),c=rstring(b),x=a[0]===0?'':a[0]===a[1]?'x':a[0]===-a[1]?'-x':k+'x';if(b[0]===0)return x||'0';return x?x+(b[0]<0?' − ':' + ')+rstring([Math.abs(b[0]),b[1]]):c;};
const term=t=>t.k==='1'?String(t.c):`${t.c===1?'':t.c===-1?'−':t.c}${t.k==='x2'?'x²':t.k==='y2'?'y²':t.k}`;
const chips=xs=>`<div class="a35-chips">${xs.map(x=>`<span>${esc(x)}</span>`).join('<b>→</b>')}</div>`;
function walk(t,b){const width=580,x=24+(b.position-t.min)/(t.max-t.min)*width;return `<div class="a35-caption">从已知的位置出发，走到目标</div><svg viewBox="0 0 628 115" class="a35-axis" aria-label="从${t.start}走到${t.target}，现在${b.position}"><line x1="24" y1="58" x2="604" y2="58"/><circle cx="${x}" cy="58" r="11"/><text x="24" y="93">${t.min}</text><text x="604" y="93" text-anchor="end">${t.max}</text><text x="${x}" y="33" text-anchor="middle">${b.position}</text></svg><div class="a35-caption">走过的步子</div>${chips(b.path.length?b.path.map(x=>(x>0?'+':'')+x):['还没走'])}`;}
function building(t,b,m){const last=b.runs.at(-1),fresh=last&&JSON.stringify(last.steps)===JSON.stringify(b.steps)&&sameNumber(last.value,m.value);return `<div class="a35-caption">把动作排成一条路</div>${chips(b.steps.length?b.steps.map(id=>t.blocks.find(x=>x.id===id)?.label):['还没有动作'])}${last?(fresh?`<p>把 ${esc(last.value)} 放进去，出来 ${esc(last.result)}；目标是 ${esc(t.target)}。</p>`:'<p>有改动，再试一次。</p>'):'<p>把一个数送进去，看看出来多少。</p>'}`;}
function trying(t,b,m){const last=b.trials.at(-1),fresh=last&&sameNumber(last.x,m.value);return `<div class="a35-caption">把数放回去，看看两边</div><div class="a35-equation">${esc(t.display)}</div>${last&&!fresh?'<p>数改了，再放回去试。</p>':last?`<div class="a35-comparison"><span>左边：${esc(last.left)}</span><b>${last.equal?'＝':'≠'}</b><span>右边：${esc(last.right)}</span></div>`:'<p>先自己挑一个数试试。</p>'}${b.trials.length?chips(b.trials.map(x=>x.x)):''}`;}
function balance(t,b,m){const left=lin(b.left),right=lin(b.right),last=b.trials.at(-1),fresh=last&&sameNumber(last.x,m.value);return `<div class="a35-caption">每一步，两边一起变化</div><svg viewBox="0 0 640 230" class="a35-balance" aria-label="等式两边：${esc(left)}等于${esc(right)}"><path d="M320 63v115M280 180h80"/><path d="M110 68h420M110 68v60M530 68v60M52 128h116M472 128h116"/><circle cx="320" cy="67" r="8"/><text x="110" y="165" text-anchor="middle">${esc(left)}</text><text x="530" y="165" text-anchor="middle">${esc(right)}</text><text x="320" y="35" text-anchor="middle">＝</text></svg>${[...b.left,...b.right].some(x=>x[0]<0)?'<p class="a35-note">这是等式变化的示意，不是把负数当成实物重量。</p>':''}${b.steps.length?`<div class="a35-caption">留下的变化</div>${chips(b.steps.map(s=>({'add':'两边加','sub':'两边减','addx':'两边加 x 的倍数','subx':'两边减 x 的倍数','mul':'两边乘','div':'两边除以'}[s.op]+' '+s.value)))}`:''}${b.preview?`<p>如果只从左边减 ${esc(b.preview.amount)}：左边 ${esc(lin(b.preview.left))}，右边仍是 ${esc(lin(b.preview.right))}。</p>`:''}${last?(fresh?`<p>把 ${esc(last.x)} 代回最初：左边 ${esc(last.left)} ${last.equal?'＝':'≠'} 右边 ${esc(last.right)}</p>`:'<p>数改了，再代回原式检查。</p>'):''}`;}
function pairs(t,b){const rows=[...b.pairs].sort((a,c)=>a[0]-c[0]);return `<div class="a35-caption">每一行是一对伙伴</div><div class="a35-pairs"><div><b>第一个数</b><b>第二个数</b></div>${rows.map(([x,y])=>`<div><span>${x}</span><span>${y}</span></div>`).join('')}</div><p class="a35-note">允许第一个数：${esc(t.rangeLabel)}。表格按第一个数排好。</p>`;}
function sort(t,b){return `<div class="a35-caption">点一张，再选放到哪一组</div><div class="a35-cards">${t.items.map((v,i)=>btn('choose',v.label,i,b.selected===i,b.assigned[i]?'disabled':'' )).join('')}</div><div class="a35-groups">${t.groups.map(g=>`<section><strong>${esc(g.label)}</strong><div>${b.assigned.map((id,i)=>id===g.id?`<span>${esc(t.items[i].label)}</span>`:'').join('')}</div>${btn('group','放到这里',g.id,false,b.selected===null?'disabled':'')}</section>`).join('')}</div>`;}
function grid(t,b){return `<div class="a35-caption">每个相遇处，都是一次相乘</div><div class="a35-product" style="--cols:${t.cols.length+1}"><span></span>${t.cols.map(c=>`<strong>${esc(term(c))}</strong>`).join('')}${t.rows.map((r,i)=>`<strong>${esc(term(r))}</strong>${t.cols.map((c,j)=>btn('cell',b.cells[i*t.cols.length+j]||'放到这格',i*t.cols.length+j,!!b.cells[i*t.cols.length+j])).join('')}`).join('')}</div>${t.extra?`<p class="a35-note">表外还有 ${esc(t.extra)}，合并时也要带上。</p>`:''}${t.negative?'<p class="a35-note">这是符号乘积表；负号不表示物理上的负面积。</p>':''}`;}
function factor(t,b,m){const last=b.trials.at(-1),fresh=last&&JSON.stringify(last.raw)===JSON.stringify({factor:m.value,power:m.second,inner:[m.third,m.fourth]});return `<div class="a35-caption">把相同的部分提出来，再乘回去</div><div class="a35-equation">${esc(t.display)}</div>${last&&!fresh?'<p>内容改了，重新展开。</p>':last?`<p>展开的两项：${last.restored.map(term).map(esc).join('，')} ${last.ok?'· 两项都回来了':'· 再和原来比较'}</p>`:'<p>先找两项都能分出的部分。</p>'}`;}
function plot(t,b){const max=t.max,pad=43,side=300,posx=x=>pad+x/max*side,posy=y=>pad+side-y/max*side,lines=Array.from({length:max+1},(_,i)=>`<line x1="${posx(i)}" y1="${pad}" x2="${posx(i)}" y2="${pad+side}"/><line x1="${pad}" y1="${posy(i)}" x2="${pad+side}" y2="${posy(i)}"/><text x="${posx(i)}" y="${pad+side+19}" text-anchor="middle">${i}</text><text x="${pad-10}" y="${posy(i)+4}" text-anchor="end">${i}</text>`).join(''),r=Array.from({length:Math.round(max/t.step)+1},(_,i)=>i*t.step),targets=r.flatMap(x=>r.map(y=>`<circle class="a35-target" data-x="a35-plot" data-px="${x}" data-py="${y}" cx="${posx(x)}" cy="${posy(y)}" r="${Math.min(8,side/max*t.step*.45)}" tabindex="0" role="button" aria-label="试点 ${x}，${y}"/>`)).join(''),last=b.trials.at(-1);return `<div class="a35-caption">一个点能同时落在两条线上吗？</div><div class="a35-graph-wrap"><svg viewBox="0 0 390 390" class="a35-graph" aria-label="两条关系画在同一个坐标图里"><defs><clipPath id="a35-clip"><rect x="${pad}" y="${pad}" width="${side}" height="${side}"/></clipPath></defs><g class="a35-gridlines">${lines}</g><g clip-path="url(#a35-clip)">${t.lines.map((l,i)=>`<line class="a35-line line${i} ${t.kind==='coincident'&&i===1?'a35-coincident':''}" x1="${posx(0)}" y1="${posy(l.b)}" x2="${posx(max)}" y2="${posy(l.m*max+l.b)}"/>`).join('')}${targets}${last?`<circle class="a35-marker" cx="${posx(last.pair[0])}" cy="${posy(last.pair[1])}" r="7"/>`:''}</g><text x="${pad+side+10}" y="${pad+side+17}">x</text><text x="${pad-13}" y="${pad-14}">y</text></svg><div><p class="a35-line-name">紫线：${esc(t.labels[0])}</p><p class="a35-line-name">绿线：${esc(t.labels[1])}</p>${last?`<p>试点（${last.pair.join('，')}）</p><p>紫线：${last.on[0]?'符合':'不符合'}<br>绿线：${last.on[1]?'符合':'不符合'}</p>`:'<p>点图上的位置，或在下面写一对数。</p>'}</div></div>`;}
export function visual(t,m){const b=m.board,v=t.type==='x-a35-walk'?walk(t,b):t.type==='x-a35-build'?building(t,b,m):t.type==='x-a35-try'?trying(t,b,m):t.type==='x-a35-balance'?balance(t,b,m):t.type==='x-a35-pairs'?pairs(t,b):t.type==='x-a35-sort'?sort(t,b):t.type==='x-a35-grid'?grid(t,b):t.type==='x-a35-factor'?factor(t,b,m):t.type==='x-a35-plot'?plot(t,b):'';return `<div class="a35-world">${v}</div>`;}
export function controls(t,m){const b=m.board;let s='<div class="a35-controls">';
 if(t.type==='x-a35-walk')s+=`<div class="a35-buttons">${t.jumps.map(n=>btn('walk',(n>0?'+':'')+n,n)).join('')}${btn('undo','退回一步')}${btn('reset','从头走')}</div>`;
 if(t.type==='x-a35-build')s+=`<div class="a35-buttons">${t.blocks.map(x=>btn('block',x.label,x.id,b.steps.includes(x.id))).join('')}${btn('undo','退回一步')}${btn('clear','重新排')}</div>`+input('value','放进去的数',m.value)+btn('run','让它走一遍');
 if(t.type==='x-a35-try')s+=input('value','先试哪个数',m.value)+btn('try','放回去看看');
 if(t.type==='x-a35-balance')s+=input('value','要用哪个数',m.value,'可以写分数，如 1/2')+`<div class="a35-buttons">${btn('op','两边都加','add')}${btn('op','两边都减','sub')}${btn('op','两边都乘','mul')}${btn('op','两边都除','div')}${btn('undo','退回一步')}${btn('reset','回到原式')}</div><details class="a35-more"><summary>两边加减 x</summary><div class="a35-buttons">${btn('op','两边加几份 x','addx')}${btn('op','两边减几份 x','subx')}</div></details><details class="a35-more"><summary>只改变一边会怎样</summary>${btn('one-side','只改左边试试','sub')}</details><div class="a35-buttons">${btn('try','把这个数代回原式')}</div>`;
 if(t.type==='x-a35-pairs')s+=input('value','第一个数',m.value)+input('second','第二个数',m.second)+btn('pair','留下一对');
 if(t.type==='x-a35-grid')s+=input('value','写出一格的乘积',m.value,'例如 3x、−6 或 x^2')+'<p>写好后，点上面对应的格子。</p>';
 if(t.type==='x-a35-factor')s+='<p>括号里依次写多少个 x，以及一个数；负数直接带上负号。</p>'+input('value','提出的数字',m.value)+select('second','提出的字母部分',m.second,[['1','没有字母'],['x','x']])+input('third','括号中第一项的数字',m.third)+input('fourth','括号中第二项的数字',m.fourth)+btn('factor','展开检查');
 if(t.type==='x-a35-plot')s+=input('value','横向 x',m.value)+input('second','纵向 y',m.second)+btn('plot','试这个点');
 for(const[i,q]of(t.questions||[]).entries())s+=q.options?select('answers.'+i,q.label,m.answers[i],q.options):input('answers.'+i,q.label,m.answers[i],q.placeholder||'');
 if(m.issue)s+=`<p class="a35-issue" role="status">${esc(m.issue)}</p>`;
 return s+`<details><summary>留下自己的想法（可选）</summary>${input('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
